/** complex form control */
export const ComplexFormControl: Story = {
  name: "complex form control",
  render: () => <Demo19 />,
  parameters: {
    docs: {
      description: { story: "Demo này cho thấy cách dùng `Form.Item` với nhiều control. `<Form.Item name=\"field\" />` chỉ bind control (Input/Select) là con duy nhất của nó. Hãy hình dung trường hợp sau: bạn thêm một đoạn văn bản mô tả sau Input, khi đó bạn phải bọc Input bằng một `<Form.Item name=\"field\">` bổ sung. Thuộc tính `style` của `Form.Item` có thể hữu ích để chỉnh bố cục mục form lồng nhau, hoặc dùng `<Form.Item noStyle />` để biến nó thành một component thuần chỉ bind form.\n\n```diff\n- <Form.Item label=\"Field\" name=\"field\">\n-   <Input />\n- </Form.Item>\n+ <Form.Item label=\"Field\" htmlFor=\"field\">\n+   <Form.Item name=\"field\" noStyle><Input id=\"field\" /></Form.Item>\n+   {/* The nested item binds the input. */}\n+   <span>description</span>\n+ </Form.Item>\n```\n\nKhi `Form.Item` bên ngoài có label nhưng không có `name`, nó không thể suy ra ID của control lồng bên trong. Nếu label mô tả một control duy nhất, hãy đặt `htmlFor` trên mục bên ngoài và cùng `id` đó trên control lồng bên trong để giữ hành vi focus khi click label và liên kết với trình đọc màn hình.\n\nDemo này cho thấy ba cách dùng điển hình:\n\n- `Username`: phần tử bổ sung sau control, dùng `<Form.Item name=\"field\" noStyle />` bên trong `Form.Item` để bind Input.\n- `Address`: hai control trên cùng một dòng, dùng hai `<Form.Item name=\"field\" noStyle />` để bind từng control.\n- `BirthDate`: hai control trên cùng một dòng với thông báo lỗi độc lập, dùng hai `<Form.Item name=\"field\" noStyle />` để bind từng control, làm bố cục inline bằng cách tuỳ chỉnh thuộc tính `style`.\n\n> Lưu ý, trong trường hợp này, Form.Item có label không được còn thuộc tính `name` nào nữa.\n\nXem demo `Customized Form Controls` bên dưới để biết cách dùng nâng cao hơn." },
      source: { code: Demo19Source, language: 'tsx' },
    },
  },
}

